/* @lc app=leetcode id=3559 lang=kotlin */ class Solution { fun lca(up: Array<IntArray>, dep: IntArray, a0: Int, b0: Int): Int = (if (dep[a0] >= dep[b0]) a0 to b0 else b0 to a0).let { (a, b) -> (0 until 17).fold(a) { x, k -> if ((dep[a] - dep[b]) shr k and 1 == 1) up[k][x] else x }.let { a1 -> if (a1 == b) a1 else (16 downTo 0).fold(a1 to b) { (x, y), k -> if (up[k][x] != up[k][y]) up[k][x] to up[k][y] else x to y }.let { (x, _) -> up[0][x] } } } fun assignEdgeWeights(edges: Array<IntArray>, queries: Array<IntArray>): IntArray = (edges.size + 1).let { N -> edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(N + 1) { -1 }.also { it[1] = 1 }.let { par -> IntArray(N + 1).let { dep -> generateSequence(listOf(1)) { f -> f.flatMap { u -> g[u].orEmpty().filter { par[it] == -1 }.onEach { v -> par.set(v, u).also { dep[v] = dep[u] + 1 } } }.takeIf { it.isNotEmpty() } }.count().let { Array(17) { IntArray(N + 1) }.also { up -> par.copyInto(up[0]) }.also { up -> (1 until 17).forEach { k -> (1..N).forEach { v -> up[k][v] = up[k - 1][up[k - 1][v]] } } }.let { up -> generateSequence(1L) { it * 2 % 1_000_000_007L }.take(N + 1).toList().let { pw -> queries.map { (u, v) -> lca(up, dep, u, v).let { l -> (dep[u] + dep[v] - 2 * dep[l]).let { L -> if (L == 0) 0 else pw[L - 1].toInt() } } }.toIntArray() } } } } } } } }